import { MeshBasicNodeMaterial } from 'three/webgpu';
import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-1-label';

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  const imageUrl = '/prism-mock/home/nodes/orb-decor.png';
  if (imageUrl && ctx.textureLoader) {
    map = ctx.textureLoader.load(imageUrl);
    if (map) {
      map.colorSpace = THREE.SRGBColorSpace;
    }
  }

  const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const surfaceColor = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 1.0);

  if (map) {
    const texNode = texture(map, uv());
    // engineered gradient blended subtly over the source image
    const gradientMix = mix(surfaceColor, inkColor, uv().y);
    material.colorNode = mix(texNode, gradientMix, float(0.08));
  } else {
    material.colorNode = mix(surfaceColor, inkColor, uv().y);
  }

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'card-1-label-plane';
  group.add(plane);

  const textMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Features 2',
    fontFamily: 'Lora',
    weight: 400,
    role: 'headline',
    sizeEm: 0.34,
    color: '#e8ecf2',
    align: 'center',
    anchor: 'middle',
    atlasIndex: 0,
    sourceRect: { x: 0, y: 0, w: 512, h: 320 },
  });

  if (textMesh) {
    textMesh.position.set(0, 0, 0.01);
    textMesh.name = 'card-1-label-text';
    group.add(textMesh);
  }

  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
